import { DateTime } from "luxon";
import { APP_TIME_ZONE, IST_OFFSET_MINUTES } from "@/lib/india";
import { isValidTimezone } from "@/lib/slots";

/**
 * Moves availability rules that were saved in another time zone to Indian Standard Time (doc/14-india-localisation.md, section 4).
 * The pure planner is here (unit-tested); the database reads and writes and the command line are in scripts/normalise-timezones.ts.
 *
 * A rule says "weekday W, HH:mm to HH:mm, in zone Z". Slots are generated by stepping from the window start, so shifting both ends by
 * the same number of minutes gives exactly the same instants. That is only true when
 *   1. the zone's UTC offset never changes over the next year (no daylight saving: "10:00 in New York" is a different IST time in
 *      summer and in winter, and one fixed IST rule cannot say that), and
 *   2. the shifted window stays on the same weekday (if it crosses midnight the weekday would change and a window could straddle two
 *      days, which a rule cannot say).
 * Anything else is REFUSED with the reason and left exactly as it is: lib/slots.ts keeps honouring a rule's stored zone, so nothing
 * changes for customers until the influencer re-enters the hours. Bookings are instants and never refer to a rule: no booked slot moves.
 */

export interface RuleInput {
  id: string;
  weekday: number;
  startTime: string;
  endTime: string;
  timezone: string;
}

export type RuleAction =
  | { kind: "already-ist" }
  | { kind: "convert"; startTime: string; endTime: string; offsetMinutes: number; shiftMinutes: number }
  | { kind: "refuse"; reason: "unknown-zone" | "dst-zone" | "crosses-midnight" | "bad-time"; detail: string };

/** How far ahead the offset of a zone is checked for changes, and how often (days). Daylight saving lasts months, so weekly is exact. */
const LOOKAHEAD_DAYS = 400;
const STEP_DAYS = 7;

const toMinutes = (t: string): number | null => {
  const m = /^([01]\d|2[0-3]):([0-5]\d)$/.exec(t);
  return m ? Number(m[1]) * 60 + Number(m[2]) : null;
};
const toClock = (min: number): string => `${String(Math.floor(min / 60)).padStart(2, "0")}:${String(min % 60).padStart(2, "0")}`;

/** The UTC offsets (minutes) a zone has at weekly samples over the next year, or null for an unknown zone. */
export function zoneOffsets(zone: string, now: Date): number[] | null {
  if (!isValidTimezone(zone)) return null;
  const out = new Set<number>();
  for (let d = 0; d <= LOOKAHEAD_DAYS; d += STEP_DAYS) {
    out.add(DateTime.fromMillis(now.getTime() + d * 86_400_000, { zone }).offset);
  }
  return [...out];
}

export function planRule(rule: RuleInput, now: Date): RuleAction {
  if (rule.timezone === APP_TIME_ZONE) return { kind: "already-ist" };
  const offsets = zoneOffsets(rule.timezone, now);
  if (!offsets) return { kind: "refuse", reason: "unknown-zone", detail: `"${rule.timezone}" is not a time zone this system knows` };
  if (offsets.length > 1) {
    return { kind: "refuse", reason: "dst-zone", detail: `${rule.timezone} changes its UTC offset during the year (daylight saving), so its wall-clock hours have no single IST equivalent` };
  }
  const start = toMinutes(rule.startTime);
  const end = toMinutes(rule.endTime);
  if (start === null || end === null || end <= start) return { kind: "refuse", reason: "bad-time", detail: `${rule.startTime}-${rule.endTime} is not a valid window` };
  const offsetMinutes = offsets[0];
  const shiftMinutes = IST_OFFSET_MINUTES - offsetMinutes;
  const ns = start + shiftMinutes;
  const ne = end + shiftMinutes;
  // The times are used literally by lib/slots.ts ("23:59" is 23:59, the latest an end can be), so the shifted window must fit 00:00-23:59.
  if (ns < 0 || ne > 24 * 60 - 1) {
    return { kind: "refuse", reason: "crosses-midnight", detail: `${rule.startTime}-${rule.endTime} ${rule.timezone} is ${toClock(((ns % 1440) + 1440) % 1440)}-${toClock(((ne % 1440) + 1440) % 1440)} IST, which is not on the same weekday` };
  }
  return { kind: "convert", startTime: toClock(ns), endTime: toClock(ne), offsetMinutes, shiftMinutes };
}

export interface InfluencerPlan {
  influencerId: string;
  slug: string;
  influencerTimezone: string;
  rules: { rule: RuleInput; action: RuleAction }[];
  /** True when, after the conversions, every rule is IST: the influencer's own zone column can be set to IST too. */
  fullyIst: boolean;
}

export function planInfluencer(
  influencer: { id: string; slug: string; timezone: string; rules: RuleInput[] },
  now: Date,
): InfluencerPlan {
  const rules = influencer.rules.map((rule) => ({ rule, action: planRule(rule, now) }));
  const fullyIst = rules.every((r) => r.action.kind === "already-ist" || r.action.kind === "convert");
  return { influencerId: influencer.id, slug: influencer.slug, influencerTimezone: influencer.timezone, rules, fullyIst };
}

export const CONFIRM_VALUE = "NORMALISE-TIMEZONES";

export interface NormaliseArgs {
  apply: boolean;
  confirm: string | null;
  help: boolean;
  unknown: string[];
}

export function parseNormaliseArgs(argv: string[]): NormaliseArgs {
  const out: NormaliseArgs = { apply: false, confirm: null, help: false, unknown: [] };
  for (const a of argv) {
    if (a === "--apply") out.apply = true;
    else if (a === "--help" || a === "-h") out.help = true;
    else if (a.startsWith("--confirm=")) out.confirm = a.slice("--confirm=".length);
    else out.unknown.push(a);
  }
  return out;
}

/** One line per rule for the dry run and the report. */
export function describeAction(rule: RuleInput, action: RuleAction): string {
  const label = `${rule.id} weekday ${rule.weekday} ${rule.startTime}-${rule.endTime} ${rule.timezone}`;
  switch (action.kind) {
    case "already-ist":
      return `${label}: already IST`;
    case "convert":
      return `${label}: CONVERT to ${action.startTime}-${action.endTime} ${APP_TIME_ZONE} (shift ${action.shiftMinutes >= 0 ? "+" : ""}${action.shiftMinutes} min)`;
    case "refuse":
      return `${label}: REFUSE (${action.reason}): ${action.detail}`;
  }
}
